$maps_000705 = [
    "resource_type_field" => array_column(ps_query("SELECT ref, name FROM resource_type_field"), "name", "ref"),
    "node"                => array_column(ps_query("SELECT ref, name FROM node WHERE resource_type_field = ?", ["i", $snaplist]), "name", "ref"),
